-- 028_warmups_supersets.sql
-- Warm-up sets and supersets in a session.
--   is_warmup       a ramp-up set before the working sets. It never counts:
--                   not in volume, records, last performance or challenges.
--   superset_group  exercises of a session sharing this number are done in a
--                   row; the rest only starts after the last one.
--
-- Deploy: apply this file first, then the code. The app sends the new
-- columns, and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE workout_sets ADD COLUMN IF NOT EXISTS is_warmup BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE workout_sets ADD COLUMN IF NOT EXISTS superset_group SMALLINT;

-- Challenge volume: same as 014, without the warm-up sets.
CREATE OR REPLACE FUNCTION get_challenge_leaderboard(p_challenge_id UUID)
RETURNS TABLE (user_id UUID, display_name TEXT, score NUMERIC)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_group UUID; v_type TEXT; v_start DATE; v_end DATE;
BEGIN
  SELECT c.group_id, c.type, c.start_date, c.end_date
    INTO v_group, v_type, v_start, v_end
  FROM challenges c WHERE c.id = p_challenge_id AND c.deleted_at IS NULL;

  IF v_group IS NULL THEN RETURN; END IF;
  IF NOT is_group_member(v_group) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN QUERY
  WITH members AS (
    -- active clients of the team + the team owner
    SELECT gm.user_id FROM group_members gm
      WHERE gm.group_id = v_group AND gm.status = 'active'
        AND gm.deleted_at IS NULL AND gm.user_id IS NOT NULL
    UNION
    SELECT g.user_id FROM groups g WHERE g.id = v_group
  ),
  scored AS (
    SELECT m.user_id,
      CASE
        WHEN v_type = 'volume' THEN COALESCE((
          SELECT SUM(ws.weight_kg * ws.reps)
          FROM workouts w
          JOIN workout_sets ws ON ws.workout_id = w.id AND ws.completed = TRUE AND NOT ws.is_warmup AND ws.deleted_at IS NULL
          WHERE w.user_id = m.user_id AND w.deleted_at IS NULL
            AND w.date BETWEEN v_start AND v_end
        ), 0)
        WHEN v_type = 'sessions' THEN COALESCE((
          SELECT COUNT(*) FROM workouts w
          WHERE w.user_id = m.user_id AND w.deleted_at IS NULL
            AND w.date BETWEEN v_start AND v_end
        ), 0)
        ELSE COALESCE((  -- consistency: distinct training days
          SELECT COUNT(DISTINCT w.date) FROM workouts w
          WHERE w.user_id = m.user_id AND w.deleted_at IS NULL
            AND w.date BETWEEN v_start AND v_end
        ), 0)
      END AS score
    FROM members m
  )
  SELECT s.user_id,
         COALESCE(p.display_name, 'Athlete') AS display_name,
         s.score
  FROM scored s
  LEFT JOIN profiles p ON p.user_id = s.user_id
  ORDER BY s.score DESC, display_name ASC;
END;
$$;

COMMIT;

-- 029_circuit_supersets.sql
-- The circuit days of the ready-made programs become supersets: each exercise
-- leads straight into the next, and the rest only comes after the last one.
-- "Lean & Strong" (both days) and "4-Day Cut" (its two circuit days), in the
-- three languages.
--
-- Only the "supersetWithNext" flag is added, on the days named below: anything
-- an admin changed in these programs is kept. Programs athletes already added
-- are their own copies and stay as they are.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

WITH circuits(name, locale, days) AS (VALUES
  ('Lean & Strong',     'en', ARRAY['Circuit A', 'Circuit B']),
  ('Sec et fort',       'fr', ARRAY['Circuit A', 'Circuit B']),
  ('Schlank & stark',   'de', ARRAY['Zirkel A', 'Zirkel B']),
  ('4-Day Cut',         'en', ARRAY['Upper circuit', 'Lower circuit']),
  ('Sèche 4 jours',     'fr', ARRAY['Circuit haut', 'Circuit bas']),
  ('Definition 4 Tage', 'de', ARRAY['Oberkörper-Zirkel', 'Unterkörper-Zirkel'])
)
UPDATE program_templates t
SET structure = (
  SELECT jsonb_agg(
    CASE WHEN day->>'name' = ANY (c.days) AND jsonb_typeof(day->'exercises') = 'array' THEN
      jsonb_set(day, '{exercises}', COALESCE((
        SELECT jsonb_agg(
          CASE WHEN e.pos < jsonb_array_length(day->'exercises')
            THEN e.exercise || '{"supersetWithNext": true}'::jsonb
            ELSE e.exercise - 'supersetWithNext'
          END ORDER BY e.pos)
        FROM jsonb_array_elements(day->'exercises') WITH ORDINALITY AS e(exercise, pos)
      ), '[]'::jsonb))
    ELSE day END
    ORDER BY d.pos)
  FROM jsonb_array_elements(t.structure) WITH ORDINALITY AS d(day, pos)
)
FROM circuits c
WHERE t.name = c.name AND t.locale = c.locale AND jsonb_array_length(t.structure) > 0;

COMMIT;

-- 030_training_schedule.sql
-- The athlete's week: the days they plan to train (1 = Monday … 7 = Sunday)
-- and the usual time, used for the week on the home screen and for the
-- calendar reminders. Kept on the athlete profile, which the athlete owns,
-- since a program assigned by a coach is read-only for them.
--
-- Deploy: apply this file first, then the code. The app sends the new
-- columns, and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS training_days JSONB;
ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS training_time TEXT;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_training_time_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_training_time_check
  CHECK (training_time IS NULL OR training_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$');

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_training_days_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_training_days_check
  CHECK (training_days IS NULL OR jsonb_typeof(training_days) = 'array');

COMMIT;

-- 031_strength_goals.sql
-- The athlete's strength goals: a target estimated one-rep max on an exercise,
-- maybe by a date. Kept on the athlete profile, which the athlete owns and the
-- coach can read; the progress itself is computed from the sessions.
--
-- Deploy: apply this file first, then the code. The app sends the new column,
-- and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS strength_goals JSONB;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_strength_goals_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_strength_goals_check
  CHECK (strength_goals IS NULL OR (jsonb_typeof(strength_goals) = 'array' AND jsonb_array_length(strength_goals) <= 20));

COMMIT;

