-- 033_deload_week.sql
-- The week an athlete chose to deload (its Monday, YYYY-MM-DD). During that
-- week the app starts sessions with fewer sets and lighter loads. Kept on the
-- athlete profile, so it follows the athlete across devices and the coach
-- sees it.
--
-- Deploy: apply this file first, then the code. The app sends the new column,
-- and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS deload_week TEXT;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_deload_week_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_deload_week_check
  CHECK (deload_week IS NULL OR deload_week ~ '^\d{4}-\d{2}-\d{2}$');

COMMIT;

-- 034_pain_reports.sql
-- A pain or discomfort reported on an exercise during a session: where it
-- hurts and how much (1-10). Stored on the workout note the athlete writes,
-- so the coach, who already reads those notes, sees it too.
--
-- Deploy: apply this file first, then the code. The app sends the new
-- columns, and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE workout_notes ADD COLUMN IF NOT EXISTS pain_area TEXT;
ALTER TABLE workout_notes ADD COLUMN IF NOT EXISTS pain_level SMALLINT;

ALTER TABLE workout_notes DROP CONSTRAINT IF EXISTS workout_notes_pain_check;
ALTER TABLE workout_notes ADD CONSTRAINT workout_notes_pain_check CHECK (
  (pain_area IS NULL AND pain_level IS NULL)
  OR (pain_area IN ('shoulder','elbow','wrist','neck','upper_back','lower_back','hip','knee','ankle','other')
      AND pain_level BETWEEN 1 AND 10)
);

COMMIT;

-- 035_program_start_date.sql
-- The day a program starts. A plan made of weeks then follows the calendar
-- from it (week 3 of 12), and a program a coach assigns starts on the day
-- chosen for the athlete.
--
-- Deploy: apply this file first, then the code. The app sends the new column,
-- and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE programs ADD COLUMN IF NOT EXISTS start_date DATE;

COMMIT;

