INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Préparation physique du voltigeur', 'Deux séances sans cheval, à la maison ou en salle : gainage, force des bras et des jambes, équilibre et souplesse, les qualités qui donnent des figures nettes. En complément des séances en club.', 'endurance', 'beginner', 2, true, '[{"name":"Force et gainage","exercises":[{"exerciseName":"Handstand Hold","targetSets":3,"targetReps":"15-30s","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Side Plank","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Tuck Jump","targetSets":3,"targetReps":"6-8","restSec":60},{"exerciseName":"Bulgarian Split Squat","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45}]},{"name":"Souplesse et équilibre","exercises":[{"exerciseName":"Front Split Stretch","targetSets":3,"targetReps":"45s","restSec":30},{"exerciseName":"Pike Stretch","targetSets":3,"targetReps":"45s","restSec":30},{"exerciseName":"Bridge Hold","targetSets":3,"targetReps":"15-20s","restSec":45},{"exerciseName":"Arabesque Hold","targetSets":3,"targetReps":"20-30s","restSec":30},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"10-12","restSec":45}]}]'::jsonb, true, 320, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Préparation physique du voltigeur' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Vaulting: get started in 8 weeks', 'To discover vaulting at a club: the compulsory figures learnt on the barrel first, then on the horse at walk and canter, and a conditioning session. Three sessions a week. Sessions on the horse always with a qualified lunger.', 'endurance', 'beginner', 3, false, '[{"name":"W1 · Barrel","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Learn the positions of the compulsories safely, without the movement of the horse.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Mount, Basic seat, Flag. 5 times each, held for 4 counted beats, with a spotter if needed","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W1 · On the horse","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Walk","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At walk: mount with the lunger’s help, then Basic seat, Flag, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W1 · Conditioning","week":1,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W2 · Barrel","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Learn the positions of the compulsories safely, without the movement of the horse.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Basic seat, Flag, Mill. 5 times each, held for 4 counted beats, with a spotter if needed","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W2 · On the horse","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Walk","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At walk: mount with the lunger’s help, then Basic seat, Flag, Mill, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W2 · Conditioning","week":2,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W3 · Barrel","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Learn the positions of the compulsories safely, without the movement of the horse.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Mill, Forward scissors. 5 times each, held for 4 counted beats, with a spotter if needed","Sequence: Mill, Forward scissors one after the other, 3 times, without touching the ground","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W3 · On the horse","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Walk","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At walk: mount with the lunger’s help, then Mill, Forward scissors, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W3 · Conditioning","week":3,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W4 · Barrel","week":4,"exercises":[],"cardio":{"sport":"vaulting","durationMin":35,"intensity":"Technique","purpose":"Lighter week: go over the figures without fatigue.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Basic seat, Flag, Mill, Forward scissors. 5 times each, held for 4 counted beats, with a spotter if needed","Sequence: Basic seat, Flag, Mill, Forward scissors one after the other, 3 times, without touching the ground","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W4 · On the horse","week":4,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Walk","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At walk: mount with the lunger’s help, then Basic seat, Flag, Mill, Forward scissors, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W4 · Conditioning","week":4,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W5 · Barrel","week":5,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Step up: the stand and the flank, on the barrel first.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Backward scissors, Stand. 5 times each, held for 4 counted beats, with a spotter if needed","Sequence: Backward scissors, Stand one after the other, 3 times, without touching the ground","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W5 · On the horse","week":5,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Canter","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At canter (at walk until the lunger judges you ready): mount, then Backward scissors, Stand, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W5 · Conditioning","week":5,"exercises":[{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"45s","restSec":30}]},{"name":"W6 · Barrel","week":6,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Step up: the stand and the flank, on the barrel first.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Stand, Flank. 5 times each, held for 4 counted beats, with a spotter if needed","Sequence: Stand, Flank one after the other, 3 times, without touching the ground","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W6 · On the horse","week":6,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Canter","purpose":"Find on the horse what you learnt on the barrel, following the rhythm of the horse.","steps":["Warm-up on the ground: 3 laps running beside the horse on the circle, then shoulder and hip mobility","At canter (at walk until the lunger judges you ready): mount, then Stand, Flank, 2 passes per figure","Controlled dismount, landing feet together and knees bent, then 5 min of stretching"],"notes":"Always with a qualified lunger and a vaulting horse, in close-fitting clothes and vaulting shoes."}},{"name":"W6 · Conditioning","week":6,"exercises":[{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"45s","restSec":30}]},{"name":"W7 · Barrel","week":7,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Link the compulsories smoothly, as in a competition.","steps":["Warm-up: 5 min easy jog, arm and hip circles, 10 jumps on the spot","Technique: Basic seat, Flag, Mill, Forward scissors, Backward scissors, Stand, Flank. 5 times each, held for 4 counted beats, with a spotter if needed","Sequence: Basic seat, Flag, Mill, Forward scissors, Backward scissors, Stand, Flank one after the other, 3 times, without touching the ground","Cool-down: 5 min stretching of the hamstrings, shoulders and hips"],"notes":"Work on the barrel over a mat, with a spotter for new figures."}},{"name":"W7 · On the horse","week":7,"exercises":[],"cardio":{"s