-- 048_program_weekdays.sql
-- The days of the week each program is trained on (1 = Monday … 7 = Sunday).
-- A program given days is in the athlete’s planning: the week on the home
-- screen and the calendar export then show every planned program together.
-- The owner sets them, as for the start date: a coach for the programs
-- given to athletes.
--
-- Deploy: apply this file first, then the code. The app sends the new column,
-- and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE programs ADD COLUMN IF NOT EXISTS weekdays JSONB;

ALTER TABLE programs DROP CONSTRAINT IF EXISTS programs_weekdays_check;
ALTER TABLE programs ADD CONSTRAINT programs_weekdays_check
  CHECK (weekdays IS NULL OR (jsonb_typeof(weekdays) = 'array' AND weekdays <@ '[1,2,3,4,5,6,7]'::jsonb));

COMMIT;

-- 049_team_invite_links.sql
-- Invitation links: a coach invites an athlete with a link (to share by
-- message, or as a QR code) instead of an e-mail address, and can prepare
-- the athlete’s arrival: a program with its start and days, and a welcome
-- message. The athlete signs up with any address and joins in one tap.
--
-- Security:
-- - The token is 244 random bits and only its SHA-256 is stored: the table
--   alone cannot open an invitation.
-- - A link is used once, expires after 14 days, and the coach can revoke it.
--   At most 50 open links per team.
-- - Nobody reads or writes the table directly: everything goes through the
--   functions below, for signed-in active accounts only (never anon).
-- - A wrong, used, revoked or expired link gives the same answer, and
--   reveals nothing.
-- - Joining is the athlete’s own act (the app asks for consent first): it
--   makes them an active member, which opens their data to the coach, as an
--   accepted e-mail invitation does.
-- - A coach’s invitation counts as approval of the account, as an admin’s
--   does: an account created with a valid link (the token is sent with the
--   sign-up), or with an address a coach invited, starts active. A link
--   approves one account only: the first one claims it, and only that one
--   can then join with it.
--
-- Deploy: apply this file first, then the code.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

CREATE TABLE IF NOT EXISTS team_invites (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  created_by UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  label TEXT CHECK (label IS NULL OR char_length(label) <= 80),
  program_name TEXT CHECK (program_name IS NULL OR char_length(program_name) <= 120),
  program_structure JSONB CHECK (
    program_structure IS NULL OR (jsonb_typeof(program_structure) = 'array' AND pg_column_size(program_structure) <= 300000)
  ),
  start_date DATE,
  weekdays JSONB CHECK (weekdays IS NULL OR (jsonb_typeof(weekdays) = 'array' AND weekdays <@ '[1,2,3,4,5,6,7]'::jsonb)),
  welcome TEXT CHECK (welcome IS NULL OR char_length(welcome) <= 2000),
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + interval '14 days',
  claimed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  used_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  used_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT team_invites_program_named CHECK (program_structure IS NULL OR program_name IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_team_invites_group ON team_invites(group_id);

-- No policy: no direct access at all, only through the functions.
ALTER TABLE team_invites ADD COLUMN IF NOT EXISTS claimed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE team_invites ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON team_invites FROM anon, authenticated;

CREATE OR REPLACE FUNCTION invite_token_hash(p_token TEXT)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
  SELECT encode(sha256(convert_to(coalesce(p_token, '-'), 'UTF8')), 'hex');
$$;

-- ─── A coach creates a link ─────────────────────────────────
CREATE OR REPLACE FUNCTION create_team_invite(
  p_group_id UUID,
  p_label TEXT DEFAULT NULL,
  p_program_name TEXT DEFAULT NULL,
  p_program JSONB DEFAULT NULL,
  p_start DATE DEFAULT NULL,
  p_weekdays JSONB DEFAULT NULL,
  p_welcome TEXT DEFAULT NULL
)
RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_owner UUID; v_token TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT is_active_account() OR NOT is_group_owner_or_manager(p_group_id) THEN
    RAISE EXCEPTION 'NOT_ALLOWED';
  END IF;
  SELECT user_id INTO v_owner FROM groups WHERE id = p_group_id AND deleted_at IS NULL;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'NOT_ALLOWED';
  END IF;
  IF NOT has_plan_feature(v_owner, 'coaching') THEN
    RAISE EXCEPTION 'PLAN_REQUIRED';
  END IF;
  IF (SELECT count(*) FROM team_invites
      WHERE group_id = p_group_id AND used_at IS NULL AND revoked_at IS NULL AND expires_at > now()) >= 50 THEN
    RAISE EXCEPTION 'TOO_MANY_INVITES';
  END IF;
  -- Two random UUIDs, 64 hex digits: 244 random bits.
  v_token := encode(uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()), 'hex');
  INSERT INTO team_invites (group_id, created_by, token_hash, label, program_name, program_structure, start_date, weekdays, welcome)
  VALUES (
    p_group_id, auth.uid(), invite_token_hash(v_token),
    CASE WHEN length(btrim(p_label)) > 0 THEN btrim(p_label) END,
    CASE WHEN p_program IS NOT NULL AND length(btrim(p_program_name)) > 0 THEN btrim(p_program_name) END,
    p_program, p_start, p_weekdays,
    CASE WHEN length(btrim(p_welcome)) > 0 THEN btrim(p_welcome) END
  );
  RETURN v_token;
END;
$$;

-- ─── The athlete sees what the link offers ──────────────────
CREATE OR REPLACE FUNCTION preview_team_invite(p_token TEXT)
RETURNS TABLE (team_name TEXT, coach_name TEXT, label TEXT, program_name TEXT, start_date DATE, weekdays JSONB, welcome TEXT)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT g.name, p.display_name, i.label, i.program_name, i.start_date, i.weekdays, i.welcome
  FROM team_invites i
  JOIN groups g ON g.id = i.group_id AND g.deleted_at IS NULL
  LEFT JOIN profiles p ON p.user_id = i.created_by
  WHERE auth.uid() IS NOT NULL AND is_active_account()
    AND i.token_hash = invite_token_hash(p_token)
    AND i.used_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
    AND (i.claimed_by IS NULL OR i.claimed_by = auth.uid());
$$;

-- ─── The athlete joins ───────────────────────────────────────
CREATE OR REPLACE FUNCTION accept_team_invite(p_token TEXT)
RETURNS TABLE (team_name TEXT, coach_name TEXT, program_id UUID)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_inv team_invites%ROWTYPE; v_owner UUID; v_email TEXT; v_program UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT is_active_account() THEN
    RAISE EXCEPTION 'INVALID_INVITE';
  END IF;
  SELECT * INTO v_inv FROM team_invites WHERE token_hash = invite_token_hash(p_token) FOR UPDATE;
  IF NOT FOUND OR v_inv.used_at IS NOT NULL OR v_inv.revoked_at IS NOT NULL OR v_inv.expires_at <= now()
     OR (v_inv.claimed_by IS NOT NULL AND v_inv.claimed_by <> auth.uid()) THEN
    RAISE EXCEPTION 'INVALID_INVITE';
  END IF;
  SELECT user_id INTO v_owner FROM groups WHERE id = v_inv.group_id AND deleted_at IS NULL;
  IF v_owner IS NULL OR NOT has_plan_feature(v_owner, 'coaching') THEN
    RAISE EXCEPTION 'INVALID_INVITE';
  END IF;
  IF v_owner = auth.uid() OR v_inv.created_by = auth.uid() THEN
    RAISE EXCEPTION 'OWN_TEAM';
  END IF;
  IF EXISTS (SELECT 1 FROM group_members
             WHERE group_id = v_inv.group_id AND user_id = auth.uid() AND status = 'active' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'ALREADY_MEMBER';
  END IF;

  -- An e-mail invitation still pending in this team becomes this membership.
  SELECT email INTO v_email FROM auth.users WHERE id = auth.uid();
  UPDATE group_members
  SET user_id = auth.uid(), status = 'active', joined_at = now()
  WHERE group_id = v_inv.group_id AND deleted_at IS NULL AND status = 'pending'
    AND (user_id = auth.uid() OR (v_email IS NOT NULL AND lower(invited_email) = lower(v_email)));
  IF NOT FOUND THEN
    INSERT INTO group_members (group_id, user_id, invited_email, role, status, joined_at)
    VALUES (v_inv.group_id, auth.uid(), lower(coalesce(v_email, auth.uid()::text)), 'member', 'active', now());
  END IF;

  UPDATE team_invites SET used_by = auth.uid(), used_at = now() WHERE id = v_inv.id;

  -- The program the coach prepared: the coach’s copy for this athlete.
  IF v_inv.program_structure IS NOT NULL THEN
    INSERT INTO programs (user_id, owner_user_id, assigned_to_user_id, group_id, name, structure, start_date, weekdays)
    VALUES (v_inv.created_by, v_inv.created_by, auth.uid(), v_inv.group_id, v_inv.program_name,
            v_inv.program_structure, v_inv.start_date, v_inv.weekdays)
    RETURNING id INTO v_program;
  END IF;
  IF v_inv.welcome IS NOT NULL THEN
    INSERT INTO messages (user_id, recipient_id, body) VALUES (v_inv.created_by, auth.uid(), v_inv.welcome);
  END IF;

  RETURN QUERY
  SELECT g.name, p.display_name, v_program
  FROM groups g LEFT JOIN profiles p ON p.user_id = v_inv.created_by
  WHERE g.id = v_inv.group_id;
END;
$$;

-- ─── The coach follows and revokes the links ────────────────
CREATE OR REPLACE FUNCTION list_team_invites(p_group_id UUID)
RETURNS TABLE (id UUID, label TEXT, program_name TEXT, start_date DATE, created_at TIMESTAMPTZ, expires_at TIMESTAMPTZ,
               used_at TIMESTAMPTZ, used_by UUID, used_by_name TEXT, revoked_at TIMESTAMPTZ)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT is_active_account() OR NOT is_group_owner_or_manager(p_group_id) THEN
    RAISE EXCEPTION 'NOT_ALLOWED';
  END IF;
  RETURN QUERY
  SELECT i.id, i.label, i.program_name, i.start_date, i.created_at, i.expires_at, i.used_at, i.used_by, p.display_name, i.revoked_at
  FROM team_invites i LEFT JOIN profiles p ON p.user_id = i.used_by
  WHERE i.group_id = p_group_id
  ORDER BY i.created_at DESC
  LIMIT 100;
END;
$$;

CREATE OR REPLACE FUNCTION revoke_team_invite(p_id UUID)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_group UUID;
BEGIN
  SELECT group_id INTO v_group FROM team_invites WHERE id = p_id;
  IF v_group IS NULL OR auth.uid() IS NULL OR NOT is_active_account() OR NOT is_group_owner_or_manager(v_group) THEN
    RAISE EXCEPTION 'NOT_ALLOWED';
  END IF;
  UPDATE team_invites SET revoked_at = now() WHERE id = p_id AND used_at IS NULL AND revoked_at IS NULL;
END;
$$;


-- ─── A coach’s invitation approves the new account ──────────
-- Same as 011, plus: a valid link sent with the sign-up (claimed by this
-- account), or a coach’s pending e-mail invitation, starts the account active.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_default_plan UUID;
  v_inv invitations%ROWTYPE;
  v_status TEXT;
  v_link UUID;
BEGIN
  SELECT id INTO v_default_plan FROM plans WHERE is_default LIMIT 1;

  SELECT * INTO v_inv FROM invitations
  WHERE lower(email) = lower(NEW.email) AND status = 'pending'
  LIMIT 1;

  -- A coach’s link, still open and not claimed by another account.
  IF NEW.raw_user_meta_data ? 'team_invite' THEN
    UPDATE team_invites i SET claimed_by = NEW.id
    WHERE i.token_hash = invite_token_hash(NEW.raw_user_meta_data->>'team_invite')
      AND i.claimed_by IS NULL AND i.used_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
      AND EXISTS (SELECT 1 FROM groups g WHERE g.id = i.group_id AND g.deleted_at IS NULL AND has_plan_feature(g.user_id, 'coaching'))
    RETURNING i.id INTO v_link;
  END IF;

  IF v_inv.id IS NOT NULL THEN
    UPDATE invitations SET status = 'accepted' WHERE id = v_inv.id;
    v_status := 'active';   -- invited by an admin: approved
  ELSIF v_link IS NOT NULL OR EXISTS (
    SELECT 1 FROM group_members gm JOIN groups g ON g.id = gm.group_id AND g.deleted_at IS NULL
    WHERE lower(gm.invited_email) = lower(NEW.email) AND gm.status = 'pending' AND gm.deleted_at IS NULL
      AND has_plan_feature(g.user_id, 'coaching')
  ) THEN
    v_status := 'active';   -- invited by a coach: approved
  ELSE
    v_status := 'pending';  -- needs admin approval
  END IF;

  INSERT INTO profiles (user_id, email, display_name, status, plan_id)
  VALUES (
    NEW.id, NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email, '@', 1)),
    v_status, v_default_plan
  );
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION create_team_invite(UUID, TEXT, TEXT, JSONB, DATE, JSONB, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION preview_team_invite(TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION accept_team_invite(TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION list_team_invites(UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION revoke_team_invite(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION create_team_invite(UUID, TEXT, TEXT, JSONB, DATE, JSONB, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION preview_team_invite(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION accept_team_invite(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION list_team_invites(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION revoke_team_invite(UUID) TO authenticated;

COMMIT;

-- 050_schedule_moves.sql
-- Sessions the athlete moved to another day, or skipped: a list of
-- { program, from, to } on the athlete’s profile (program = the program’s
-- uuid, from and to = dates, to = null for a session skipped). Kept on the
-- profile rather than on the program, since a coach’s program is only read
-- by the athlete. The app drops the moves over a month old and keeps 40.
--
-- Deploy: apply this file first, then the code. The app sends the new column,
-- and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS schedule_moves JSONB;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_schedule_moves_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_schedule_moves_check
  CHECK (
    schedule_moves IS NULL
    OR (jsonb_typeof(schedule_moves) = 'array'
        AND jsonb_array_length(schedule_moves) <= 60
        AND pg_column_size(schedule_moves) <= 16384)
  );

COMMIT;

-- 051_run_paces_meal_prefs.sql
-- On the athlete’s profile:
-- - run_paces: the VMA (maximal aerobic speed, km/h) and what it came from
--   (a race result, the half-Cooper test, or typed in). The app works every
--   running pace out of it.
-- - meal_prefs: the diet, the foods left out and the meals a day, for the
--   meal ideas.
--
-- Deploy: apply this file first, then the code. The app sends the new
-- columns, and the server refuses columns it does not know.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS run_paces JSONB;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_run_paces_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_run_paces_check
  CHECK (
    run_paces IS NULL
    OR (jsonb_typeof(run_paces) = 'object'
        AND pg_column_size(run_paces) <= 1024
        AND CASE WHEN jsonb_typeof(run_paces->'vma') = 'number'
                 THEN (run_paces->>'vma')::numeric BETWEEN 8 AND 26
                 ELSE false END)
  );

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS meal_prefs JSONB;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_meal_prefs_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_meal_prefs_check
  CHECK (
    meal_prefs IS NULL
    OR (jsonb_typeof(meal_prefs) = 'object' AND pg_column_size(meal_prefs) <= 1024)
  );

COMMIT;

-- 052_plan_features_checked.sql
-- Licences: more features to tick, and the server checks them on what is saved.
--
-- New features: running, meal_plans, level_tests, planning, reports,
-- excel_import, challenges, vaulting. Every licence that exists gets them
-- all, so no one loses anything: untick them afterwards on the admin page.
--
-- Checked by the server (refused with PLAN_REQUIRED without the feature):
-- - readiness_checkins: readiness
-- - nutrition_entries, hydration_logs: nutrition
-- - competition_results, horses, horse_sessions: vaulting
-- - athlete_profiles: run_paces (running), meal_prefs (meal_plans),
--   schedule_moves (planning), when they change
-- - create_challenge: challenges
-- Deleting stays possible, and what was saved before stays readable.
-- The rest (level tests, reports, Excel import) is worked out on the device.
--
-- Deploy: apply this file first, then the code.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

-- ─── The new features, on every licence ──────────────────────────

UPDATE plans
SET features = (
  SELECT COALESCE(jsonb_agg(DISTINCT f ORDER BY f), '[]'::jsonb)
  FROM jsonb_array_elements_text(
    COALESCE(features, '[]'::jsonb)
    || '["running","meal_plans","level_tests","planning","reports","excel_import","challenges","vaulting"]'::jsonb
  ) AS f
);

-- ─── The check ───────────────────────────────────────────────────

-- The caller’s licence must include the feature. A call without a user
-- (the service itself, scheduled jobs) passes.
CREATE OR REPLACE FUNCTION require_plan_feature(p_feature TEXT)
RETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT has_plan_feature(auth.uid(), p_feature) THEN
    RAISE EXCEPTION 'PLAN_REQUIRED: %', p_feature USING ERRCODE = '42501';
  END IF;
END;
$$;

-- Rows of a feature: written only with it, deleted (deleted_at) always.
-- An upsert of a row that exists is checked as the update that follows.
CREATE OR REPLACE FUNCTION enforce_plan_feature_rows()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_exists BOOLEAN;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    v_exists := CASE TG_TABLE_NAME
      WHEN 'readiness_checkins' THEN EXISTS (SELECT 1 FROM readiness_checkins r WHERE r.id = NEW.id)
      WHEN 'nutrition_entries' THEN EXISTS (SELECT 1 FROM nutrition_entries r WHERE r.id = NEW.id)
      WHEN 'hydration_logs' THEN EXISTS (SELECT 1 FROM hydration_logs r WHERE r.id = NEW.id)
      WHEN 'competition_results' THEN EXISTS (SELECT 1 FROM competition_results r WHERE r.id = NEW.id)
      WHEN 'horses' THEN EXISTS (SELECT 1 FROM horses r WHERE r.id = NEW.id)
      WHEN 'horse_sessions' THEN EXISTS (SELECT 1 FROM horse_sessions r WHERE r.id = NEW.id)
      ELSE false
    END;
    IF v_exists THEN
      RETURN NEW;
    END IF;
  END IF;
  PERFORM require_plan_feature(TG_ARGV[0]);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS readiness_checkins_plan ON readiness_checkins;
CREATE TRIGGER readiness_checkins_plan BEFORE INSERT OR UPDATE ON readiness_checkins
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('readiness');

DROP TRIGGER IF EXISTS nutrition_entries_plan ON nutrition_entries;
CREATE TRIGGER nutrition_entries_plan BEFORE INSERT OR UPDATE ON nutrition_entries
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('nutrition');

DROP TRIGGER IF EXISTS hydration_logs_plan ON hydration_logs;
CREATE TRIGGER hydration_logs_plan BEFORE INSERT OR UPDATE ON hydration_logs
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('nutrition');

DROP TRIGGER IF EXISTS competition_results_plan ON competition_results;
CREATE TRIGGER competition_results_plan BEFORE INSERT OR UPDATE ON competition_results
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('vaulting');

DROP TRIGGER IF EXISTS horses_plan ON horses;
CREATE TRIGGER horses_plan BEFORE INSERT OR UPDATE ON horses
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('vaulting');

DROP TRIGGER IF EXISTS horse_sessions_plan ON horse_sessions;
CREATE TRIGGER horse_sessions_plan BEFORE INSERT OR UPDATE ON horse_sessions
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_rows('vaulting');

-- The profile: some of its columns belong to a feature. Checked when they
-- change to something (clearing them stays possible).
CREATE OR REPLACE FUNCTION enforce_plan_feature_profile()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_old athlete_profiles%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM athlete_profiles a WHERE a.id = NEW.id) THEN
      RETURN NEW;
    END IF;
  ELSE
    v_old := OLD;
  END IF;
  IF NEW.run_paces IS NOT NULL AND NEW.run_paces IS DISTINCT FROM v_old.run_paces THEN
    PERFORM require_plan_feature('running');
  END IF;
  IF NEW.meal_prefs IS NOT NULL AND NEW.meal_prefs IS DISTINCT FROM v_old.meal_prefs THEN
    PERFORM require_plan_feature('meal_plans');
  END IF;
  IF NEW.schedule_moves IS NOT NULL AND jsonb_typeof(NEW.schedule_moves) = 'array'
     AND jsonb_array_length(NEW.schedule_moves) > 0
     AND NEW.schedule_moves IS DISTINCT FROM v_old.schedule_moves THEN
    PERFORM require_plan_feature('planning');
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS athlete_profiles_plan ON athlete_profiles;
CREATE TRIGGER athlete_profiles_plan BEFORE INSERT OR UPDATE ON athlete_profiles
  FOR EACH ROW EXECUTE FUNCTION enforce_plan_feature_profile();

-- ─── Challenges: created with the feature ────────────────────────

CREATE OR REPLACE FUNCTION create_challenge(
  p_group_id UUID, p_name TEXT, p_type TEXT, p_start DATE, p_end DATE
) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_id UUID;
BEGIN
  IF NOT is_group_owner_or_manager(p_group_id) THEN
    RAISE EXCEPTION 'Unauthorized: not the team trainer';
  END IF;
  PERFORM require_plan_feature('challenges');
  IF p_type NOT IN ('volume', 'sessions', 'consistency') THEN
    RAISE EXCEPTION 'Invalid challenge type';
  END IF;
  INSERT INTO challenges (group_id, created_by, name, type, start_date, end_date)
  VALUES (p_group_id, auth.uid(), p_name, p_type, p_start, p_end)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION require_plan_feature(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION require_plan_feature(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION create_challenge(UUID, TEXT, TEXT, DATE, DATE) TO authenticated;

COMMIT;

-- 053_more_timed_exercises.sql
-- Timed sessions (callisthenics): 41 more exercises in the library, in
-- English, French and German. Cardio without the hands on the floor, more for
-- the legs and the abs, push-up variants and a few with dumbbells.
--
-- Deploy: apply this file first, then the code (the app would otherwise add
-- them as the athlete’s own exercises the first time).
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, v.name, v.muscle_group, v.equipment, false, v.description, v.name_fr, v.name_de, v.description_fr, v.description_de
FROM (VALUES
  ('Butt Kicks', 'full_body', 'bodyweight', 'Run on the spot, bringing the heels up to the glutes, fast and light on the feet.', 'Talons-fesses', 'Anfersen', 'Courir sur place en ramenant les talons vers les fessiers, vite et léger sur les appuis.', 'Auf der Stelle laufen und die Fersen schnell zum Gesäß ziehen, leichtfüßig.'),
  ('Fast Feet', 'legs', 'bodyweight', 'Slightly crouched, tap the feet as fast as possible on the balls of the feet.', 'Pas rapides sur place', 'Schnelle Füße', 'Légèrement fléchi, piétiner le plus vite possible sur l’avant des pieds.', 'Leicht gebeugt so schnell wie möglich auf den Fußballen trippeln.'),
  ('Lateral Shuffle', 'legs', 'bodyweight', 'Knees bent, shuffle three steps sideways and back, staying low, without crossing the feet.', 'Pas chassés latéraux', 'Seitliche Sidesteps', 'Genoux fléchis, trois pas chassés sur le côté puis retour, en restant bas, sans croiser les pieds.', 'Mit gebeugten Knien drei Sidesteps zur Seite und zurück, tief bleiben, Füße nicht kreuzen.'),
  ('Step Jack', 'full_body', 'bodyweight', 'Step one foot out to the side and back, then the other, fast, without jumping. Arms stay low.', 'Jumping jack sans saut', 'Hampelmann ohne Sprung', 'Écarter un pied sur le côté puis le ramener, puis l’autre, vite, sans sauter. Les bras restent bas.', 'Einen Fuß zur Seite setzen und zurück, dann den anderen, zügig, ohne Sprung. Arme bleiben unten.'),
  ('Standing Knee Drive', 'core', 'bodyweight', 'Standing tall, drive one knee up to hip height and back, then the other, fast, abs tight.', 'Montées de genou debout', 'Kniehub im Stehen', 'Debout bien droit, monter un genou à hauteur de hanche puis l’autre, vite, abdos serrés.', 'Aufrecht stehend abwechselnd ein Knie zügig auf Hüfthöhe ziehen, Bauch fest.'),
  ('Star Jump', 'full_body', 'bodyweight', 'Squat slightly, then jump up spreading arms and legs in a star, land softly feet together.', 'Saut en étoile', 'Sternsprung', 'Fléchir un peu, puis sauter en écartant bras et jambes en étoile, se réceptionner pieds joints en douceur.', 'Leicht in die Knie, dann mit gespreizten Armen und Beinen als Stern springen, weich mit geschlossenen Füßen landen.'),
  ('Broad Jump', 'legs', 'bodyweight', 'Swing the arms and jump forward as far as possible, land softly in a squat, walk back.', 'Saut en longueur', 'Weitsprung aus dem Stand', 'Lancer les bras et sauter vers l’avant le plus loin possible, se réceptionner en squat en douceur, revenir en marchant.', 'Mit Armschwung so weit wie möglich nach vorne springen, weich in der Hocke landen, zurückgehen.'),
  ('Shadow Boxing', 'full_body', 'bodyweight', 'In a guard stance, throw quick punches straight ahead, light on the feet, without locking the elbows.', 'Boxe dans le vide', 'Schattenboxen', 'En garde, enchaîner des coups de poing rapides devant soi, léger sur les appuis, sans verrouiller les coudes.', 'In Deckung schnelle gerade Schläge nach vorne, leichtfüßig, Ellbogen nicht durchstrecken.'),
  ('Squat Thrust', 'full_body', 'bodyweight', 'Squat, hands on the floor, jump the feet back to a plank, jump them back in and stand up.', 'Squat thrust', 'Squat Thrust', 'Descendre en squat, mains au sol, sauter les pieds en arrière en planche, les ramener et se relever.', 'In die Hocke, Hände auf den Boden, Füße in den Stütz springen, zurückspringen und aufrichten.'),
  ('Plank Jack', 'core', 'bodyweight', 'In a high plank, jump the feet apart and back together, hips level.', 'Planche jumping jack', 'Plank Jacks', 'En planche bras tendus, écarter et resserrer les pieds en sautant, hanches à niveau.', 'Im hohen Stütz die Füße auseinander und wieder zusammen springen, Hüfte gerade.'),
  ('Bear Crawl', 'full_body', 'bodyweight', 'On hands and feet, knees just off the floor, crawl forward and back with small steps, back flat.', 'Marche de l’ours', 'Bärengang', 'À quatre pattes, genoux juste décollés, avancer puis reculer à petits pas, dos plat.', 'Im Vierfüßlerstand, Knie knapp über dem Boden, mit kleinen Schritten vor und zurück krabbeln, Rücken gerade.'),
  ('Sumo Squat', 'legs', 'bodyweight', 'Wide stance, toes out, squat down with the knees over the toes, chest up, stand up.', 'Squat sumo', 'Sumo-Kniebeuge', 'Pieds écartés, pointes vers l’extérieur, descendre genoux au-dessus des pieds, buste droit, remonter.', 'Breiter Stand, Fußspitzen nach außen, Knie über den Zehen absenken, Brust aufrecht, hochkommen.'),
  ('Squat Pulse', 'legs', 'bodyweight', 'Hold the bottom of a squat and move up and down a few centimetres, without standing up.', 'Squat pulsé', 'Kniebeuge-Pulse', 'Tenir le bas du squat et monter-descendre de quelques centimètres, sans se relever.', 'Unten in der Kniebeuge bleiben und wenige Zentimeter auf und ab federn, ohne aufzustehen.'),
  ('Lateral Lunge', 'legs', 'bodyweight', 'Step wide to one side, sit back on that leg with the other straight, push back. Alternate sides.', 'Fente latérale', 'Seitlicher Ausfallschritt', 'Faire un grand pas sur le côté, s’asseoir sur cette jambe l’autre tendue, revenir. Alterner.', 'Großer Schritt zur Seite, auf dieses Bein setzen, das andere gestreckt, zurückdrücken. Abwechseln.'),
  ('Curtsy Lunge', 'legs', 'bodyweight', 'Step one leg back and across behind the other, lower the knee, return. Alternate legs.', 'Fente croisée', 'Curtsy Lunge', 'Reculer une jambe en la croisant derrière l’autre, descendre le genou, revenir. Alterner.', 'Ein Bein hinter dem anderen überkreuzt nach hinten setzen, Knie absenken, zurück. Abwechseln.'),
  ('Split Squat', 'legs', 'bodyweight', 'In a long stride, lower the back knee towards the floor and push back up, feet staying put.', 'Fente statique', 'Split Squat', 'En grande fente, descendre le genou arrière vers le sol et remonter, sans bouger les pieds.', 'In weiter Schrittstellung das hintere Knie Richtung Boden senken und hochdrücken, Füße bleiben stehen.'),
  ('Cossack Squat', 'legs', 'bodyweight', 'Very wide stance, sit down on one leg, the other straight with toes up, then shift to the other side.', 'Squat cosaque', 'Kosaken-Kniebeuge', 'Pieds très écartés, s’asseoir sur une jambe, l’autre tendue pointe en l’air, puis passer de l’autre côté.', 'Sehr breiter Stand, auf ein Bein setzen, das andere gestreckt mit Zehen nach oben, dann zur anderen Seite.'),
  ('Single-Leg Glute Bridge', 'legs', 'bodyweight', 'On your back, one foot on the floor and the other leg up, drive the hips up and squeeze the glutes.', 'Pont fessier sur une jambe', 'Einbeinige Glute Bridge', 'Sur le dos, un pied au sol et l’autre jambe levée, monter les hanches en serrant les fessiers.', 'In Rückenlage, ein Fuß am Boden, das andere Bein oben, Hüfte anheben und Gesäß anspannen.'),
  ('Bodyweight Calf Raise', 'legs', 'bodyweight', 'Standing, rise onto the toes as high as possible, pause, lower slowly.', 'Montées sur pointes', 'Wadenheben ohne Gewicht', 'Debout, monter sur la pointe des pieds le plus haut possible, marquer un temps, redescendre lentement.', 'Im Stand so hoch wie möglich auf die Zehenspitzen, kurz halten, langsam absenken.'),
  ('Good Morning', 'legs', 'bodyweight', 'Hands on the hips, knees soft, hinge forward with a flat back until the chest is near horizontal, stand up.', 'Good morning', 'Good Morning', 'Mains sur les hanches, genoux souples, basculer le buste dos plat presque à l’horizontale, se redresser.', 'Hände an der Hüfte, Knie locker, mit geradem Rücken nach vorne beugen fast bis zur Waagerechten, aufrichten.'),
  ('Donkey Kick', 'legs', 'bodyweight', 'On all fours, knee bent, push one heel up towards the ceiling without arching the back.', 'Kick arrière à quatre pattes', 'Donkey Kick', 'À quatre pattes, genou fléchi, pousser un talon vers le plafond sans cambrer.', 'Im Vierfüßlerstand mit gebeugtem Knie eine Ferse Richtung Decke drücken, ohne Hohlkreuz.'),
  ('Fire Hydrant', 'legs', 'bodyweight', 'On all fours, lift one bent knee out to the side to hip height, lower it with control.', 'Fire hydrant (ouverture de hanche)', 'Fire Hydrant', 'À quatre pattes, lever un genou fléchi sur le côté à hauteur de hanche, redescendre en contrôlant.', 'Im Vierfüßlerstand ein gebeugtes Knie seitlich auf Hüfthöhe heben, kontrolliert absenken.'),
  ('Knee Push-up', 'chest', 'bodyweight', 'Hands under the shoulders, knees on the floor, body in a straight line, knees to head, lower the chest and push up.', 'Pompes sur les genoux', 'Liegestütze auf den Knien', 'Mains sous les épaules, genoux au sol, corps aligné des genoux à la tête, descendre la poitrine et pousser.', 'Hände unter den Schultern, Knie am Boden, Körper gerade von Knie bis Kopf, Brust absenken und hochdrücken.'),
  ('Incline Push-up', 'chest', 'bodyweight', 'Hands on a chair or a bench, body straight, lower the chest to the edge and push back up.', 'Pompes inclinées', 'Schräge Liegestütze', 'Mains sur une chaise ou un banc, corps gainé, descendre la poitrine vers le bord et remonter.', 'Hände auf einem Stuhl oder einer Bank, Körper gerade, Brust zur Kante senken und hochdrücken.'),
  ('Diamond Push-up', 'arms', 'bodyweight', 'Hands together under the chest, thumbs and index fingers touching, lower the chest and push up, elbows close.', 'Pompes diamant', 'Diamant-Liegestütze', 'Mains jointes sous la poitrine, pouces et index qui se touchent, descendre et pousser, coudes serrés.', 'Hände unter der Brust, Daumen und Zeigefinger berühren sich, absenken und hochdrücken, Ellbogen eng.'),
  ('Pike Push-up', 'shoulders', 'bodyweight', 'Hips high in an upside-down V, bend the elbows to bring the head towards the floor, push back up.', 'Pompes en V (pike)', 'Pike-Liegestütze', 'Hanches hautes en V inversé, plier les coudes pour amener la tête vers le sol, repousser.', 'Hüfte hoch im umgekehrten V, Ellbogen beugen und den Kopf Richtung Boden senken, hochdrücken.'),
  ('Bench Dip', 'arms', 'bodyweight', 'Hands on the edge of a chair behind you, legs out, bend the elbows to lower the hips, push back up.', 'Dips sur une chaise', 'Dips an der Stuhlkante', 'Mains sur le bord d’une chaise derrière soi, jambes devant, plier les coudes pour descendre les hanches, remonter.', 'Hände hinter dir auf einer Stuhlkante, Beine nach vorne, Ellbogen beugen, Hüfte senken, hochdrücken.'),
  ('Heel Taps', 'core', 'bodyweight', 'On your back, knees bent, shoulders lifted, reach side to side to touch each heel.', 'Touches de talons', 'Fersen-Tippen', 'Sur le dos, genoux fléchis, épaules décollées, aller toucher chaque talon d’un côté puis de l’autre.', 'In Rückenlage, Knie gebeugt, Schultern angehoben, abwechselnd seitlich zu den Fersen greifen.'),
  ('Reverse Crunch', 'core', 'bodyweight', 'On your back, knees bent at 90 degrees, roll the hips off the floor towards the chest, lower slowly.', 'Crunch inversé', 'Reverse Crunch', 'Sur le dos, genoux à 90 degrés, enrouler le bassin vers la poitrine, redescendre lentement.', 'In Rückenlage, Knie im rechten Winkel, das Becken Richtung Brust einrollen, langsam absenken.'),
  ('Scissor Kicks', 'core', 'bodyweight', 'On your back, legs straight and lifted, cross them one over the other, lower back on the floor.', 'Ciseaux', 'Scherenbeine', 'Sur le dos, jambes tendues décollées, les croiser l’une sur l’autre, le bas du dos au sol.', 'In Rückenlage die gestreckten Beine anheben und überkreuzen, unterer Rücken am Boden.'),
  ('V-up', 'core', 'bodyweight', 'Lying flat, lift the legs and the chest at the same time to touch the toes, lower with control.', 'V-up', 'V-Up', 'Allongé, lever en même temps jambes et buste pour toucher les pieds, redescendre en contrôlant.', 'Flach liegend Beine und Oberkörper gleichzeitig heben, die Zehen berühren, kontrolliert absenken.'),
  ('Sit-up', 'core', 'bodyweight', 'On your back, knees bent, roll up to sitting, then lower slowly, hands at the temples.', 'Relevés de buste', 'Sit-up', 'Sur le dos, genoux fléchis, s’enrouler jusqu’à la position assise, puis redescendre lentement.', 'In Rückenlage mit gebeugten Knien bis zum Sitzen aufrollen, dann langsam ablegen.'),
  ('Standing Oblique Crunch', 'core', 'bodyweight', 'Standing, hands behind the head, bring one knee up to the side to meet the elbow, alternate.', 'Crunch oblique debout', 'Seitlicher Crunch im Stehen', 'Debout, mains derrière la tête, monter un genou sur le côté vers le coude, alterner.', 'Im Stand, Hände hinter dem Kopf, ein Knie seitlich zum Ellbogen ziehen, abwechseln.'),
  ('Glute Bridge Hold', 'core', 'bodyweight', 'On your back, knees bent, lift the hips and hold them high, glutes and abs tight.', 'Pont fessier tenu', 'Glute Bridge halten', 'Sur le dos, genoux fléchis, monter les hanches et les tenir hautes, fessiers et abdos serrés.', 'In Rückenlage mit gebeugten Knien die Hüfte heben und oben halten, Gesäß und Bauch fest.'),
  ('Side Plank Hip Dip', 'core', 'bodyweight', 'In a side plank on the forearm, lower the hip towards the floor and lift it back up.', 'Planche latérale avec descente de hanche', 'Seitstütz mit Hüftsenken', 'En planche latérale sur l’avant-bras, descendre la hanche vers le sol puis la remonter.', 'Im Seitstütz auf dem Unterarm die Hüfte Richtung Boden senken und wieder heben.'),
  ('Dumbbell Bent-Over Row', 'back', 'dumbbell', 'Bent forward with a flat back, a dumbbell in each hand, pull them to the hips, lower with control.', 'Rowing buste penché aux haltères', 'Vorgebeugtes Kurzhantelrudern', 'Penché en avant dos plat, un haltère dans chaque main, les tirer vers les hanches, redescendre en contrôlant.', 'Mit geradem Rücken vorgebeugt, je eine Kurzhantel, zur Hüfte ziehen, kontrolliert absenken.'),
  ('Dumbbell Floor Press', 'chest', 'dumbbell', 'On your back, knees bent, press the dumbbells up, lower until the upper arms touch the floor.', 'Développé au sol aux haltères', 'Kurzhantel-Bodendrücken', 'Sur le dos, genoux fléchis, pousser les haltères vers le haut, redescendre jusqu’à poser les bras au sol.', 'In Rückenlage mit gebeugten Knien die Kurzhanteln hochdrücken, absenken bis die Oberarme den Boden berühren.'),
  ('Dumbbell Curl to Press', 'shoulders', 'dumbbell', 'Curl the dumbbells to the shoulders, then press them overhead, lower in reverse.', 'Curl puis développé aux haltères', 'Curl mit Schulterdrücken', 'Monter les haltères aux épaules en curl, puis les pousser au-dessus de la tête, redescendre en sens inverse.', 'Kurzhanteln zu den Schultern curlen, dann über Kopf drücken, in umgekehrter Reihenfolge absenken.'),
  ('Dumbbell Lateral Lunge', 'legs', 'dumbbell', 'A dumbbell held at the chest, step wide to one side and sit back on that leg, push back. Alternate.', 'Fente latérale avec haltère', 'Seitlicher Ausfallschritt mit Kurzhantel', 'Un haltère contre la poitrine, grand pas sur le côté et s’asseoir sur cette jambe, revenir. Alterner.', 'Kurzhantel vor der Brust, großer Schritt zur Seite und auf dieses Bein setzen, zurückdrücken. Abwechseln.'),
  ('Dumbbell Glute Bridge', 'legs', 'dumbbell', 'On your back, a dumbbell on the hips, drive the hips up and squeeze the glutes, lower slowly.', 'Pont fessier avec haltère', 'Glute Bridge mit Kurzhantel', 'Sur le dos, un haltère sur les hanches, monter les hanches en serrant les fessiers, redescendre lentement.', 'In Rückenlage, Kurzhantel auf der Hüfte, Hüfte anheben, Gesäß anspannen, langsam absenken.'),
  ('Dumbbell Hammer Curl', 'arms', 'dumbbell', 'Standing, palms facing each other, curl the dumbbells to the shoulders, lower slowly.', 'Curl marteau aux haltères', 'Hammer-Curl mit Kurzhanteln', 'Debout, paumes face à face, monter les haltères vers les épaules, redescendre lentement.', 'Im Stand, Handflächen zueinander, Kurzhanteln zu den Schultern curlen, langsam absenken.')
) AS v(name, muscle_group, equipment, description, name_fr, name_de, description_fr, description_de)
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE e.user_id IS NULL AND e.name = v.name);

COMMIT;

-- 054_injury_programs.sql
-- Nine programs for an injured athlete, one per area (shoulder, elbow, wrist,
-- neck, upper back, lower back, hip, knee, ankle), in French, English and
-- German. None of their exercises loads the area, by the app's injury rules.
-- The app files them on a shelf of their own, "For an injury", by their name.
--
-- Deploy: apply this file, in any order with the code. Online, the app
-- shows the catalogue of this table: the programs appear once it is applied.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Épaule blessée : jambes et abdos', 'Trois séances pour garder le rythme sans solliciter l''épaule : jambes, fessiers, abdos et gainage au sol, rien au-dessus de la tête ni en poussée. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Jambes","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Walking Lunge","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Abdos et gainage","exercises":[{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45},{"exerciseName":"Lying Leg Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Bicycle Crunch","targetSets":3,"targetReps":"20","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60}]},{"name":"Fessiers et jambes","exercises":[{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Bulgarian Split Squat","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Flutter Kicks","targetSets":3,"targetReps":"20-30s","restSec":45}]}]'::jsonb, true, 400, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Épaule blessée : jambes et abdos' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Coude blessé : sans flexion des bras', 'Trois séances sans curl ni développé : le haut du corps travaille bras tendus, le bas du corps et les abdos comme d''habitude. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Haut du corps bras tendus","exercises":[{"exerciseName":"Cable Fly","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Straight-Arm Pulldown","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Rear Delt Fly","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Bas du corps","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Fessiers et épaules","exercises":[{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Walking Lunge","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lying Leg Raise","targetSets":3,"targetReps":"12-15","restSec":45}]}]'::jsonb, true, 410, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Coude blessé : sans flexion des bras' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Poignet blessé : sans barre', 'Trois séances aux haltères, poulies et machines, sans barre ni appui sur les mains : tout le corps continue de travailler. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Haut du corps","exercises":[{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Hammer Curl","targetSets":3,"targetReps":"10-12","restSec":60}]},{"name":"Bas du corps","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Corps complet","exercises":[{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]}]'::jsonb, true, 420, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Poignet blessé : sans barre' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Nuque blessée : sans charge sur la nuque', 'Trois séances complètes sans barre sur les épaules, sans charge au-dessus de la tête ni crunch qui tire sur la nuque. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Séance A","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Séance B","exercises":[{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]},{"name":"Séance C","exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lying Leg Raise","targetSets":3,"targetReps":"12-15","restSec":45}]}]'::jsonb, true, 430, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Nuque blessée : sans charge sur la nuque' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Haut du dos blessé : machines et haltères', 'Trois séances sans soulevé de terre ni rowing lourd à la barre : machines, haltères et gainage pour tout le reste du corps. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Séance A","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Séance B","exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Cable Fly","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]},{"name":"Séance C","exercises":[{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]}]'::jsonb, true, 440, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Haut du dos blessé : machines et haltères' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Bas du dos blessé : sans charge sur le dos', 'Trois séances sans squat, soulevé de terre ni rowing penché : le haut du corps sur banc et poulies, les jambes sur machines, un gainage doux. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Haut du corps","exercises":[{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Cable Fly","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Jambes sur machines","exercises":[{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Haut du corps et mollets","exercises":[{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Straight-Arm Pulldown","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]}]'::jsonb, true, 450, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Bas du dos blessé : sans charge sur le dos' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Hanche blessée : haut du corps', 'Trois séances centrées sur le haut du corps, avec des jambes sur machines qui ne sollicitent pas la hanche. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Poussée","exercises":[{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Triceps Pushdown","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Tirage","exercises":[{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Dumbbell Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Jambes sur machines","exercises":[{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Cable Fly","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]}]'::jsonb, true, 460, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Hanche blessée : haut du corps' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Genou blessé : haut du corps et hanches', 'Trois séances sans squat, fente ni saut : le haut du corps, et des fessiers et ischios travaillés genoux peu fléchis. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Haut du corps","exercises":[{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Hanches et fessiers","exercises":[{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Standing Calf Raise","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Haut du corps et bras","exercises":[{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Hammer Curl","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Triceps Pushdown","targetSets":3,"targetReps":"10-12","restSec":60}]}]'::jsonb, true, 470, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Genou blessé : haut du corps et hanches' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Cheville blessée : assis et allongé', 'Trois séances sans saut, fente ni travail debout sur les jambes : machines, banc et exercices au sol. À faire sans douleur, avec l''accord d''un professionnel de santé.', 'general', 'beginner', 3, false, '[{"name":"Séance A","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]},{"name":"Séance B","exercises":[{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Séance C","exercises":[{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]}]'::jsonb, true, 480, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Cheville blessée : assis et allongé' AND locale = 'fr');

