SELECT 'Verletzter Nacken: ohne Last auf dem Nacken', 'Drei Ganzkörpereinheiten ohne Langhantel auf den Schultern, nichts über Kopf und keine Crunches, die am Nacken ziehen. Schmerzfrei trainieren, mit dem Einverständnis einer medizinischen Fachperson.', 'general', 'beginner', 3, false, '[{"name":"Einheit A","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Einheit B","exercises":[{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Hip Thrust","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]},{"name":"Einheit C","exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lying Leg Raise","targetSets":3,"targetReps":"12-15","restSec":45}]}]'::jsonb, true, 430, 'de'
