SELECT 'Verletzter unterer Rücken: ohne Last auf der Wirbelsäule', 'Drei Einheiten ohne Kniebeugen, Kreuzheben und vorgebeugtes Rudern: Oberkörper auf der Bank und am Kabelzug, Beine an Maschinen, sanftes Rumpftraining. Schmerzfrei trainieren, mit dem Einverständnis einer medizinischen Fachperson.', 'general', 'beginner', 3, false, '[{"name":"Oberkörper","exercises":[{"exerciseName":"Dumbbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Cable Fly","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Face Pull","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Dead Bug","targetSets":3,"targetReps":"10-12","restSec":45}]},{"name":"Beine an Maschinen","exercises":[{"exerciseName":"Leg Extension","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Leg Curl","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"8-10","restSec":45}]},{"name":"Oberkörper und Waden","exercises":[{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Straight-Arm Pulldown","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Lateral Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Crunch","targetSets":3,"targetReps":"15-20","restSec":45}]}]'::jsonb, true, 450, 'de'
