-- 055_trx.sql
-- Suspension straps (TRX): 17 exercises in the library, in English, French
-- and German, and two programs (beginner and intermediate) in the three
-- languages. The app files them on a TRX shelf, offers TRX straps in the
-- equipment of the sign-up and of the timed sessions.
--
-- Deploy: apply this file first, then the code (the app would otherwise add
-- the exercises as the athlete’s own the first time).
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Row', 'back', 'suspension', false, 'Facing the anchor, hold the handles and lean back, arms straight and body in a line. Pull the chest to the hands, lower slowly. Walk the feet forward to make it harder.', 'Tirage TRX', 'TRX-Rudern', 'Face à l''ancrage, poignées en main, se pencher en arrière bras tendus, corps gainé. Tirer la poitrine vers les mains, redescendre lentement. Avancer les pieds pour corser.', 'Zum Ankerpunkt gewandt, Griffe fassen und mit gestreckten Armen zurücklehnen, Körper gerade. Brust zu den Händen ziehen, langsam ablassen. Füße nach vorn setzen macht es schwerer.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Row');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Chest Press', 'chest', 'suspension', false, 'Facing away from the anchor, lean forward on the handles, arms straight. Lower the chest between the hands, push back up. Step back to make it easier.', 'Développé pectoraux TRX', 'TRX-Brustpresse', 'Dos à l''ancrage, en appui sur les poignées bras tendus, corps penché. Descendre la poitrine entre les mains, repousser. Reculer les pieds pour faciliter.', 'Vom Ankerpunkt abgewandt, mit gestreckten Armen auf die Griffe lehnen. Brust zwischen die Hände senken, wieder hochdrücken. Füße zurücksetzen macht es leichter.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Chest Press');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Squat', 'legs', 'suspension', false, 'Facing the anchor, hold the handles with straight arms. Sit back into a deep squat, chest up, and stand up, the straps only for balance.', 'Squat TRX', 'TRX-Kniebeuge', 'Face à l''ancrage, poignées en main bras tendus. Descendre en squat profond, buste droit, et remonter : les sangles servent juste à l''équilibre.', 'Zum Ankerpunkt gewandt, Griffe mit gestreckten Armen halten. Tief in die Kniebeuge setzen, Brust aufrecht, wieder aufstehen – die Bänder nur zur Balance.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Squat');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Suspended Lunge', 'legs', 'suspension', false, 'Facing away, one foot in the cradles behind you. Bend the front leg to lower the back knee, push back up through the front heel. Switch legs halfway.', 'Fente pied suspendu TRX', 'TRX-Ausfallschritt', 'Dos à l''ancrage, un pied dans les sangles derrière soi. Fléchir la jambe avant pour descendre le genou arrière, remonter en poussant sur le talon avant. Changer de jambe à mi-temps.', 'Vom Ankerpunkt abgewandt, ein Fuß hinten in den Schlaufen. Vorderes Bein beugen, bis das hintere Knie sinkt, über die vordere Ferse hochdrücken. Zur Hälfte Bein wechseln.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Suspended Lunge');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Hamstring Curl', 'legs', 'suspension', false, 'On your back, heels in the cradles. Lift the hips, pull the heels to the glutes, then extend the legs slowly, hips up.', 'Leg curl TRX', 'TRX-Beinbeuger', 'Sur le dos, talons dans les sangles. Monter les hanches, ramener les talons vers les fessiers, puis tendre les jambes lentement en gardant les hanches hautes.', 'Auf dem Rücken, Fersen in den Schlaufen. Hüfte heben, Fersen zum Gesäß ziehen, dann die Beine langsam strecken, Hüfte oben.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Hamstring Curl');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Pike', 'core', 'suspension', false, 'In a high plank, feet in the cradles. Lift the hips high with straight legs, then lower back to the plank without sagging.', 'Pike TRX', 'TRX-Pike', 'En planche bras tendus, pieds dans les sangles. Monter les hanches très haut jambes tendues, puis revenir en planche sans creuser le dos.', 'Im hohen Stütz, Füße in den Schlaufen. Hüfte mit gestreckten Beinen hoch anheben, dann zurück in den Stütz, ohne durchzuhängen.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Pike');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Knee Tuck', 'core', 'suspension', false, 'In a high plank, feet in the cradles. Pull both knees to the chest, then extend back to the plank.', 'Genoux-poitrine TRX', 'TRX-Knieanzug', 'En planche bras tendus, pieds dans les sangles. Ramener les deux genoux vers la poitrine, puis revenir en planche.', 'Im hohen Stütz, Füße in den Schlaufen. Beide Knie zur Brust ziehen, dann zurück in den Stütz.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Knee Tuck');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Mountain Climber', 'core', 'suspension', false, 'In a high plank, feet in the cradles. Drive the knees to the chest one after the other, fast, hips low.', 'Mountain climber TRX', 'TRX-Mountain-Climber', 'En planche bras tendus, pieds dans les sangles. Ramener les genoux vers la poitrine l''un après l''autre, vite, hanches basses.', 'Im hohen Stütz, Füße in den Schlaufen. Knie abwechselnd schnell zur Brust ziehen, Hüfte tief.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Mountain Climber');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Plank', 'core', 'suspension', false, 'Forearms on the floor, feet in the cradles, body in a straight line. Hold without letting the hips drop.', 'Gainage pieds suspendus TRX', 'TRX-Unterarmstütz', 'Avant-bras au sol, pieds dans les sangles, corps aligné. Tenir sans laisser tomber les hanches.', 'Unterarme am Boden, Füße in den Schlaufen, Körper in einer Linie. Halten, ohne die Hüfte sinken zu lassen.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Plank');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Side Plank', 'core', 'suspension', false, 'On one forearm, feet stacked in the cradles. Lift the hips in a straight line and hold. Switch sides halfway.', 'Gainage latéral TRX', 'TRX-Seitstütz', 'Sur un avant-bras, pieds l''un sur l''autre dans les sangles. Monter les hanches dans l''alignement et tenir. Changer de côté à mi-temps.', 'Auf einem Unterarm, Füße übereinander in den Schlaufen. Hüfte in eine Linie heben und halten. Zur Hälfte Seite wechseln.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Side Plank');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Biceps Curl', 'arms', 'suspension', false, 'Facing the anchor, palms up, lean back with straight arms. Curl the hands to the forehead, elbows high, lower slowly.', 'Curl biceps TRX', 'TRX-Bizepscurl', 'Face à l''ancrage, paumes vers le haut, se pencher en arrière bras tendus. Fléchir les bras pour amener les mains au front, coudes hauts, redescendre lentement.', 'Zum Ankerpunkt gewandt, Handflächen nach oben, mit gestreckten Armen zurücklehnen. Hände zur Stirn beugen, Ellbogen hoch, langsam ablassen.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Biceps Curl');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Triceps Extension', 'arms', 'suspension', false, 'Facing away, arms straight overhead on the handles. Lean forward bending only the elbows, then push back to straight arms.', 'Extension triceps TRX', 'TRX-Trizepsstrecken', 'Dos à l''ancrage, bras tendus au-dessus de la tête sur les poignées. Se pencher en avant en pliant seulement les coudes, puis repousser bras tendus.', 'Vom Ankerpunkt abgewandt, Arme gestreckt über dem Kopf an den Griffen. Nur durch Beugen der Ellbogen nach vorn lehnen, dann zurück zu gestreckten Armen drücken.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Triceps Extension');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Y-Fly', 'shoulders', 'suspension', false, 'Facing the anchor, lean back with straight arms. Raise the arms in a Y above the head, squeezing the shoulder blades, lower slowly.', 'Élévation en Y TRX', 'TRX-Y-Heben', 'Face à l''ancrage, se pencher en arrière bras tendus. Monter les bras en Y au-dessus de la tête en serrant les omoplates, redescendre lentement.', 'Zum Ankerpunkt gewandt, mit gestreckten Armen zurücklehnen. Arme in einem Y über den Kopf heben, Schulterblätter zusammen, langsam ablassen.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Y-Fly');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Jump Squat', 'legs', 'suspension', false, 'Facing the anchor, holding the handles. Squat down, jump up, land softly back in the squat.', 'Squat sauté TRX', 'TRX-Sprungkniebeuge', 'Face à l''ancrage, poignées en main. Descendre en squat, sauter, se réceptionner en douceur dans le squat.', 'Zum Ankerpunkt gewandt, Griffe halten. In die Kniebeuge gehen, hochspringen, weich in der Kniebeuge landen.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Jump Squat');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Atomic Push-up', 'chest', 'suspension', false, 'Feet in the cradles, hands on the floor. Do a push-up, then pull the knees to the chest, extend back.', 'Pompe atomique TRX', 'TRX-Atomic-Liegestütz', 'Pieds dans les sangles, mains au sol. Faire une pompe, puis ramener les genoux vers la poitrine, et revenir.', 'Füße in den Schlaufen, Hände am Boden. Einen Liegestütz machen, dann die Knie zur Brust ziehen und zurück.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Atomic Push-up');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Single-Leg Squat', 'legs', 'suspension', false, 'Facing the anchor, holding the handles, on one leg, the other forward. Squat down on the standing leg and stand up. Switch legs halfway.', 'Squat sur une jambe TRX', 'Einbeinige TRX-Kniebeuge', 'Face à l''ancrage, poignées en main, sur une jambe, l''autre tendue devant. Descendre sur la jambe d''appui et remonter. Changer de jambe à mi-temps.', 'Zum Ankerpunkt gewandt, Griffe halten, auf einem Bein, das andere nach vorn. Auf dem Standbein beugen und aufstehen. Zur Hälfte Bein wechseln.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Single-Leg Squat');

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, 'TRX Sprinter Start', 'legs', 'suspension', false, 'Facing away, leaning forward on the handles in a sprinter stance. Drive one knee up fast and back down. Switch legs halfway.', 'Départ de sprinteur TRX', 'TRX-Sprinterstart', 'Dos à l''ancrage, penché en avant sur les poignées comme au départ d''un sprint. Monter un genou vite puis le redescendre. Changer de jambe à mi-temps.', 'Vom Ankerpunkt abgewandt, in Sprinterhaltung nach vorn auf die Griffe gelehnt. Ein Knie schnell hochziehen und absetzen. Zur Hälfte Bein wechseln.'
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE user_id IS NULL AND name = 'TRX Sprinter Start');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
