-- 073_week_availability.sql
-- The days and minutes the athlete can train in a given week
-- ({"monday": "YYYY-MM-DD", "days": [{"weekday": 1-7, "minutes": n}]}): the
-- assistant proposes to fit that week's planned sessions to it (moves, skips,
-- short versions), applied only when the athlete says so.
-- Safe to run again.

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS week_availability JSONB;

-- 074_sport_choice_and_session_details.sql
-- The favourite sport follows the athlete from one device to another: it was
-- kept on the device only. favorite_sport holds a sport of the app's registry,
-- 'all' (all sports, nothing put first) or 'none' (chosen: none); NULL means
-- never chosen on any device yet. second_sport is the one practised alongside.
-- The values are checked by the app (its list of sports grows without a
-- migration); here only their length.
-- A session also gets the time it started ('HH:MM', local time) and its goal
-- in a sentence, both optional, under "More details".
-- Safe to run again.

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS favorite_sport TEXT;
ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS second_sport TEXT;

ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_favorite_sport_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_favorite_sport_check
  CHECK (favorite_sport IS NULL OR char_length(favorite_sport) BETWEEN 1 AND 40) NOT VALID;
ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_second_sport_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_second_sport_check
  CHECK (second_sport IS NULL OR char_length(second_sport) BETWEEN 1 AND 40) NOT VALID;

ALTER TABLE workouts ADD COLUMN IF NOT EXISTS start_time TEXT;
ALTER TABLE workouts ADD COLUMN IF NOT EXISTS session_goal TEXT;

ALTER TABLE workouts DROP CONSTRAINT IF EXISTS workouts_start_time_check;
ALTER TABLE workouts ADD CONSTRAINT workouts_start_time_check
  CHECK (start_time IS NULL OR start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') NOT VALID;
ALTER TABLE workouts DROP CONSTRAINT IF EXISTS workouts_session_goal_check;
ALTER TABLE workouts ADD CONSTRAINT workouts_session_goal_check
  CHECK (session_goal IS NULL OR char_length(session_goal) <= 200) NOT VALID;

-- 075_goals.sql
-- Goals of every kind, each one a row the athlete owns and the coach can read:
--   strength  an estimated one-rep max on an exercise (kg)
--   time      a time on a distance in a sport, e.g. 10 km under 50 min (seconds)
--   distance  a distance covered in a sport from the goal's start (metres)
--   frequency sessions a week, all of them or of one kind (sessions)
--   weight    a body weight (kg)
-- scope is the sport (time, distance) or what is counted (frequency: 'all',
-- 'strength', 'mobility' or a sport). priority 1 is the main goal, shown on the
-- home screen; 2 the others. Progress is computed from the sessions, never
-- stored.
-- The strength goals kept on the profile until now (031) are copied over, with
-- a stable id: running this again copies nothing twice. The profile column is
-- left as it was.
-- Deploy: apply this file first, then the code.
-- Safe to run again. All-or-nothing: one transaction.

BEGIN;

CREATE TABLE IF NOT EXISTS goals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  scope TEXT,
  exercise_uuid UUID,
  exercise_name TEXT,
  distance_m NUMERIC,
  target_value NUMERIC NOT NULL,
  start_value NUMERIC,
  deadline DATE,
  priority SMALLINT NOT NULL DEFAULT 2,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  deleted_at TIMESTAMPTZ,
  CONSTRAINT goals_check CHECK (
    type IN ('strength', 'time', 'distance', 'frequency', 'weight')
    AND (scope IS NULL OR char_length(scope) BETWEEN 1 AND 40)
    AND (exercise_name IS NULL OR char_length(exercise_name) BETWEEN 1 AND 120)
    AND (distance_m IS NULL OR (distance_m > 0 AND distance_m <= 1000000))
    AND target_value > 0 AND target_value <= 10000000
    AND (start_value IS NULL OR (start_value >= 0 AND start_value <= 10000000))
    AND priority BETWEEN 1 AND 3
    AND (type <> 'strength' OR exercise_name IS NOT NULL)
    AND (type <> 'time' OR (scope IS NOT NULL AND distance_m IS NOT NULL))
    AND (type <> 'distance' OR scope IS NOT NULL)
  )
);
CREATE INDEX IF NOT EXISTS idx_goals_user ON goals(user_id, updated_at);

DROP TRIGGER IF EXISTS trg_goals_updated ON goals;
CREATE TRIGGER trg_goals_updated BEFORE UPDATE ON goals FOR EACH ROW EXECUTE FUNCTION update_updated_at();

ALTER TABLE goals ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "goals_own_all" ON goals;
CREATE POLICY "goals_own_all" ON goals
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "goals_trainer_read" ON goals;
CREATE POLICY "goals_trainer_read" ON goals FOR SELECT USING (is_my_client(user_id));

-- Like every table a member's app reads or writes: active accounts only.
DROP POLICY IF EXISTS "active_account_only" ON goals;
CREATE POLICY "active_account_only" ON goals AS RESTRICTIVE FOR ALL TO authenticated
  USING ((SELECT is_active_account())) WITH CHECK ((SELECT is_active_account()));

-- The strength goals of the profiles, copied once.
INSERT INTO goals (id, user_id, type, exercise_uuid, exercise_name, target_value, start_value, deadline, priority, created_at, updated_at)
SELECT
  md5(p.user_id::text || ':' || (g->>'id'))::uuid,
  p.user_id,
  'strength',
  CASE WHEN (g->>'exerciseUuid') ~ '^[0-9a-fA-F-]{36}$' THEN (g->>'exerciseUuid')::uuid END,
  left(g->>'exerciseName', 120),
  CASE WHEN (g->>'targetKg') ~ '^[0-9]+(\.[0-9]+)?$' THEN (g->>'targetKg')::numeric END,
  CASE WHEN (g->>'startKg') ~ '^[0-9]+(\.[0-9]+)?$' THEN (g->>'startKg')::numeric ELSE 0 END,
  CASE WHEN (g->>'deadline') ~ '^\d{4}-\d{2}-\d{2}$' THEN (g->>'deadline')::date END,
  2,
  CASE WHEN (g->>'createdAt') ~ '^\d{4}-\d{2}-\d{2}T' THEN (g->>'createdAt')::timestamptz ELSE now() END,
  now()
FROM athlete_profiles p
CROSS JOIN LATERAL jsonb_array_elements(p.strength_goals) AS g
WHERE p.user_id IS NOT NULL
  AND p.deleted_at IS NULL
  AND jsonb_typeof(p.strength_goals) = 'array'
  AND g ? 'id'
  AND char_length(COALESCE(g->>'exerciseName', '')) > 0
  AND (CASE WHEN (g->>'targetKg') ~ '^[0-9]+(\.[0-9]+)?$' THEN (g->>'targetKg')::numeric ELSE 0 END) > 0
ON CONFLICT (id) DO NOTHING;

COMMIT;

-- 076_exercise_details_and_restrictions.sql
-- The library says more about each exercise, and the athlete can rule some out.
--   exercises.level              beginner / intermediate / advanced
--   exercises.movements          what it asks of the body (squat, hinge, lunge, push or
--                                pull, overhead, hanging, jumps, core...), several at once
--   exercises.secondary_muscles  the muscle groups it works besides its main one
--   exercises.cues / mistakes    the key points and the usual faults, by language
--                                ({"fr": [...], "en": [...], "de": [...]}), filled by an admin
--   exercises.variant_of         the exercise it is a variant of
--   athlete_profiles.restrictions what the athlete rules out besides an injured joint:
--                                a muscle group, a movement or an exercise, to avoid or to
--                                do with caution, maybe until a date
--                                ([{"kind": "muscle"|"movement"|"exercise", "value": ...,
--                                   "level": "avoid"|"caution", "until": "YYYY-MM-DD"}])
-- The library's 141 exercises get their level, movements and secondary muscles;
-- a row an admin already filled is left as it is.
-- Deploy: apply this file first, then the code.
-- Safe to run again. All-or-nothing: one transaction.

BEGIN;

ALTER TABLE exercises ADD COLUMN IF NOT EXISTS level TEXT;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS movements JSONB;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS secondary_muscles JSONB;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS cues JSONB;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS mistakes JSONB;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS variant_of UUID;

ALTER TABLE exercises DROP CONSTRAINT IF EXISTS exercises_details_check;
ALTER TABLE exercises ADD CONSTRAINT exercises_details_check CHECK (
  (level IS NULL OR level IN ('beginner', 'intermediate', 'advanced'))
  AND (movements IS NULL OR (jsonb_typeof(movements) = 'array' AND jsonb_array_length(movements) <= 6
       AND movements <@ '["squat", "hinge", "lunge", "push_horizontal", "push_vertical", "pull_horizontal", "pull_vertical", "overhead", "hanging", "isolation", "core_flexion", "core_stability", "rotation", "jump", "conditioning", "mobility"]'::jsonb))
  AND (secondary_muscles IS NULL OR (jsonb_typeof(secondary_muscles) = 'array' AND jsonb_array_length(secondary_muscles) <= 6
       AND secondary_muscles <@ '["chest", "back", "legs", "shoulders", "arms", "core", "full_body", "other"]'::jsonb))
  AND (cues IS NULL OR (jsonb_typeof(cues) = 'object' AND char_length(cues::text) <= 6000))
  AND (mistakes IS NULL OR (jsonb_typeof(mistakes) = 'object' AND char_length(mistakes::text) <= 6000))
) NOT VALID;

ALTER TABLE athlete_profiles ADD COLUMN IF NOT EXISTS restrictions JSONB;
ALTER TABLE athlete_profiles DROP CONSTRAINT IF EXISTS athlete_profiles_restrictions_check;
ALTER TABLE athlete_profiles ADD CONSTRAINT athlete_profiles_restrictions_check CHECK (
  restrictions IS NULL OR (jsonb_typeof(restrictions) = 'array' AND jsonb_array_length(restrictions) <= 30
    AND char_length(restrictions::text) <= 8000)
) NOT VALID;

-- Admin: the details of any exercise, the library's included. The table's
-- check refuses what does not fit; an empty value clears it.
CREATE OR REPLACE FUNCTION admin_set_exercise_details(
  p_uuid TEXT, p_level TEXT, p_movements JSONB, p_secondary JSONB, p_cues JSONB, p_mistakes JSONB, p_variant_of TEXT
)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS '
BEGIN
  IF NOT is_app_admin() THEN
    RAISE EXCEPTION ''Unauthorized: admin access required'';
  END IF;
  UPDATE exercises
     SET level = NULLIF(p_level, ''''),
         movements = CASE WHEN p_movements IS NULL OR p_movements = ''[]''::jsonb THEN NULL ELSE p_movements END,
         secondary_muscles = CASE WHEN p_secondary IS NULL OR p_secondary = ''[]''::jsonb THEN NULL ELSE p_secondary END,
         cues = CASE WHEN p_cues IS NULL OR p_cues = ''{}''::jsonb THEN NULL ELSE p_cues END,
         mistakes = CASE WHEN p_mistakes IS NULL OR p_mistakes = ''{}''::jsonb THEN NULL ELSE p_mistakes END,
         variant_of = NULLIF(p_variant_of, '''')::uuid,
         updated_at = now()
   WHERE id = p_uuid::uuid;
END;
';
REVOKE ALL ON FUNCTION admin_set_exercise_details(TEXT, TEXT, JSONB, JSONB, JSONB, JSONB, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION admin_set_exercise_details(TEXT, TEXT, JSONB, JSONB, JSONB, JSONB, TEXT) TO authenticated;

-- The library, described.
