-- 077_normalized_power.sql
-- The normalized power of a ride, from a watch or bike-computer file (FIT or
-- TCX): the steady power its ups and downs cost. When known, the intensity
-- factor and the TSS use it instead of the average power.
-- Deploy: apply this file first, then the code.
-- Safe to run again.

ALTER TABLE workouts ADD COLUMN IF NOT EXISTS normalized_power_w INT;
ALTER TABLE workouts DROP CONSTRAINT IF EXISTS workouts_normalized_power_check;
ALTER TABLE workouts ADD CONSTRAINT workouts_normalized_power_check
  CHECK (normalized_power_w IS NULL OR normalized_power_w BETWEEN 0 AND 3000) NOT VALID;

-- 078_session_provenance.sql
-- Where a session came from, so the same outing is never logged twice:
--   source       'manual' (or NULL), 'file' (a watch file), and later a
--                connected service: 'strava', 'garmin', 'health'
--   external_id  the service's own id of the activity
--   started_at   when the activity started, as the file says
--   file_hash    SHA-256 of the file it was imported from (64 hex characters)
-- The app refuses a file already imported (same fingerprint, or same sport
-- started within two minutes). A connected service writes each activity
-- once: one row per (user, source, external_id).
-- Deploy: apply this file first, then the code.
-- Safe to run again. All-or-nothing: one transaction.

BEGIN;

ALTER TABLE workouts ADD COLUMN IF NOT EXISTS source TEXT;
ALTER TABLE workouts ADD COLUMN IF NOT EXISTS external_id TEXT;
ALTER TABLE workouts ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ;
ALTER TABLE workouts ADD COLUMN IF NOT EXISTS file_hash TEXT;

ALTER TABLE workouts DROP CONSTRAINT IF EXISTS workouts_provenance_check;
ALTER TABLE workouts ADD CONSTRAINT workouts_provenance_check CHECK (
  (source IS NULL OR source IN ('manual', 'file', 'strava', 'garmin', 'health'))
  AND (external_id IS NULL OR char_length(external_id) BETWEEN 1 AND 120)
  AND (file_hash IS NULL OR file_hash ~ '^[0-9a-f]{64}$')
) NOT VALID;

CREATE INDEX IF NOT EXISTS idx_workouts_file_hash ON workouts(user_id, file_hash) WHERE file_hash IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_workouts_external ON workouts(user_id, source, external_id)
  WHERE external_id IS NOT NULL AND deleted_at IS NULL;

COMMIT;

-- 079_exercise_cues.sql
-- The key points (3) and the usual faults (2) of each of the library's 141
-- exercises, in French, English and German ({"fr": [...], "en": [...], "de": [...]}),
-- shown on the exercise's card. What an admin already wrote is kept: only
-- an exercise without them is filled. Editable afterwards in the admin.
-- Needs 076 (the columns). Safe to run again. All-or-nothing: one transaction.

BEGIN;

UPDATE exercises SET cues = '{"fr": ["Serrer les omoplates et garder les pieds ancrés au sol", "Descendre la barre au bas des pectoraux, coudes à environ 45°", "Pousser la barre en gardant les poignets au-dessus des coudes"], "en": ["Pinch the shoulder blades and keep the feet planted", "Lower the bar to the lower chest, elbows at about 45°", "Press the bar up with wrists stacked over the elbows"], "de": ["Zieh die Schulterblätter zusammen und stell die Füße fest auf", "Senk die Stange zur unteren Brust, Ellbogen bei etwa 45°", "Drück die Stange hoch, Handgelenke über den Ellbogen"]}'::jsonb, updated_at = now() WHERE user_id IS NULL AND name = 'Barbell Bench Press' AND cues IS NULL;
UPDATE exercises SET mistakes = '{"fr": ["Écarter les coudes à 90° du corps", "Faire rebondir la barre sur la poitrine"], "en": ["Flaring the elbows out to 90°", "Bouncing the bar off the chest"], "de": ["Ellbogen auf 90° abspreizen", "Die Stange von der Brust abfedern"]}'::jsonb, updated_at = now() WHERE user_id IS NULL AND name = 'Barbell Bench Press' AND mistakes IS NULL;
UPDATE exercises SET cues = '{"fr": ["Régler le banc à environ 30-45°", "Descendre la barre vers le haut des pectoraux", "Garder les omoplates serrées et le haut du dos stable"], "en": ["Set the bench to about 30-45°", "Lower the bar to the upper chest", "Keep the shoulder blades retracted and the upper back stable"], "de": ["Stell die Bank auf etwa 30-45° ein", "Senk die Stange zur oberen Brust", "Halte die Schulterblätter zurückgezogen und den oberen Rücken stabil"]}'::jsonb, updated_at = now() WHERE user_id IS NULL AND name = 'Incline Barbell Bench Press' AND cues IS NULL;
