UPDATE exercises SET target_muscles = '["obliques", "abs"]'::jsonb, assist_muscles = '["front_delts"]'::jsonb, updated_at = now() WHERE user_id IS NULL AND name = 'Shadow Boxing Body Shots' AND target_muscles IS NULL;
